import json,re,subprocess
def run(args):
 p=subprocess.run(args,capture_output=True,text=True,timeout=12)
 return p.returncode,p.stdout,p.stderr
code,stdout,stderr=run(['docker','logs','--tail','45','ai-core-model-gate'])
