codes=[]
for line in lines:
 m=re.search(r'MODEL_GATE=FAIL[|]([A-Z0-9_]+)',line)
 if m:codes.append(m.group(1))
 m=re.search(r'([A-Za-z]+(?:Error|Exception)):\s*([A-Z0-9_]+)?',line)
 if m:codes.append(m.group(1)+':'+(m.group(2) or ''))
inspect=run(['docker','inspect','-f','{{.State.Status}}|{{.State.ExitCode}}|{{.State.Restarting}}|{{.State.Health.Status}}','ai-core-model-gate'])
