 try:
  pairs=json.loads(env_names[1])
  for s in pairs:
   if s.startswith('AI_CORE_API_KEY='):
    present=True
    enough=len(s.split('=',1)[1])>=16
 except Exception:pass
out={'container_status':inspect[1].strip(),'log_exit':code,'log_line_count':len(lines),'startup_error_codes':codes[-15:],'key_mapped':present,'key_min_length_met':enough,'secret_values_printed':False}
